/* From Uiverse.io by Brola2008 - Tags: gradient, card, box-shadow */
.__UIV_SCOPE__ .one-div {
  width: 190px;
  height: 250px;
  background: linear-gradient(-45deg, rgb(9, 16, 109) ,  rgba(0,255,239,1));
  border-radius: 20px;
  box-shadow: 10px 10px 15px rgba(0, 0, 0, 0.5);
  transition: 0.5s ease;
}

.__UIV_SCOPE__ .one-div::after {
  content: "HOVER ME";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%);
  font-weight: bold;
  text-shadow: 1px 1px 4px rgb(0,0,0);
  transition: .3s;
}

.__UIV_SCOPE__ .one-div:hover {
  scale: 1.1;
  border-radius: 20px 80px;
  box-shadow: 11px 11px 25px rgba(0, 0, 0, 0.5);
}

.__UIV_SCOPE__ .one-div:hover::after {
  content: "THANKS";
  color: aqua;
}
